fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    let mut result = Vec::with_capacity(a.len());
    
    for s in a {
        if maxsplit == 0 {
            // If maxsplit is 0, return the original string in a single-element vector
            result.push(vec![s]);
            continue;
        }
        
        let mut parts = Vec::new();
        let mut remaining = s.as_str();
        let mut splits = 0;

        // Perform the right-split operation
        while splits < maxsplit && remaining.contains(&sep) {
            // Split from the end
            if let Some(pos) = remaining.rfind(&sep) {
                // Push the part after the last separator
                parts.push(remaining.split_off(pos));
                // Update remaining to the part before the last separator
                remaining = &remaining[..pos];
                splits += 1;
            }
        }
        
        // Push the remaining part (which may be empty)
        parts.push(remaining.to_string());
        
        // Reverse the parts to maintain the right-split order
        parts.reverse();
        result.push(parts);
    }
    
    result
}